def JamesTreeCoefficientBound (S : JamesTreeSegmentFamily) (d : DyadicTreeNode → 𝕜)
    (C : ℝ) : Prop :=
  ∀ A, S.allows A → ∃ c : 𝕜, ‖c‖ + ∑ t ∈ A, ‖d t-c‖ ≤ C

